 if type(source)is not str:raise ValueError("rate_reservation_text_required")
 source=source.replace("\r\n","\n")
 if "\r"in source or hashlib.sha256(source.encode()).hexdigest()!=expected:raise ValueError("rate_reservation_exact_source_required")
 return source

